use crate::{model::*,unit_support::*,msbq01 as b};
fn setup()->(Game,String,String){let mut g=game();g.players[0].society_zone.card=Some(g.make_card(b::ID,0));let host=field(&mut g,"JC029",0);fund(&mut g,0,"JC029",8);let blood=attach(&mut g,"XQ14",&host);(g,host,blood)}
fn drain(g:&mut Game){for _ in 0..60{if g.pending.is_none()&&g.stack.is_empty(){return;}if g.pending.is_some(){choose(g,vec![]);}else{pass(g);}}panic!()}
#[test]fn msbq01_return_holds_actual_blood_decline_buries_owner_once(){let(mut g,host,blood)=setup();g.return_hand(&host);g.drive().unwrap();assert!(g.attachments.iter().all(|a|a.card.id!=blood));assert!(g.players[0].graveyard.iter().all(|c|c.definition!="XQ14"));assert_eq!(g.death_replacements.len(),1);restore(&mut g);choose(&mut g,vec![]);drain(&mut g);assert!(g.death_replacements.is_empty());assert_eq!(g.players[0].graveyard.iter().filter(|c|c.definition=="XQ14").count(),1);}
#[test]fn msbq01_return_accept_seals_on_exact_personal_society(){let(mut g,host,_)=setup();g.return_hand(&host);g.drive().unwrap();restore(&mut g);choose(&mut g,vec!["accept".into()]);drain(&mut g);assert_eq!(g.sealed_cards.iter().filter(|c|c.card.definition=="XQ14"&&c.host_id=="society:p0").count(),1);assert!(g.players[0].graveyard.iter().all(|c|c.definition!="XQ14"));}
fn bad(g:&Game,x:&Game){assert!(Game::from_persisted(&serde_json::to_string(x).unwrap()).is_err());let mut r=crate::jc029_tests::envelope(g);r.game=x.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
#[test]fn msbq01_personal_not_teammate_and_hidden_does_not_qualify(){for hidden in [false,true]{let(mut g,host,_)=setup();if hidden{g.board_mut(&host).unwrap().face_down=true;}else{let teammate=(1..g.players.len()).find(|seat|g.team(*seat)==g.team(0)).unwrap();g.board_mut(&host).unwrap().controller=teammate;}g.return_hand(&host);g.drive().unwrap();assert!(g.death_replacements.is_empty());assert!(g.pending.is_none());assert_eq!(g.players[0].graveyard.iter().filter(|c|c.definition=="XQ14").count(),1);}}
#[test]fn msbq01_death_hide_and_bottom_use_one_same_destination_protocol(){for cause in 0..3{let(mut g,host,_)=setup();match cause{0=>g.remove_dead(&host,RemovalCause::Destroy),1=>{assert!(g.hide_in_place(&host));},_=>g.to_bottom(&host)}g.drive().unwrap();assert!(g.pending.is_some());restore(&mut g);choose(&mut g,vec!["accept".into()]);drain(&mut g);assert_eq!(g.sealed_cards.iter().filter(|c|c.card.definition=="XQ14").count(),1);assert!(g.death_replacements.is_empty());}}
#[test]fn msbq01_replaced_or_missing_original_society_falls_back(){for missing in [false,true]{let(mut g,host,_)=setup();g.return_hand(&host);g.drive().unwrap();choose(&mut g,vec!["accept".into()]);g.players[0].society_zone.card=if missing{None}else{Some(g.make_card(b::ID,0))};restore(&mut g);drain(&mut g);assert!(g.sealed_cards.is_empty());assert_eq!(g.players[0].graveyard.iter().filter(|c|c.definition=="XQ14").count(),1);}}
#[test]fn msbq01_actual_attachment_owner_is_preserved(){let(mut g,host,blood)=setup();let a=g.attachments.iter_mut().find(|a|a.card.id==blood).unwrap();a.card.owner=1;a.card.controller=1;g.return_hand(&host);g.drive().unwrap();choose(&mut g,vec![]);drain(&mut g);assert_eq!(g.players[1].graveyard.iter().filter(|c|c.definition=="XQ14").count(),1);assert!(g.players[0].graveyard.iter().all(|c|c.definition!="XQ14"));}
#[test]fn msbq01_multiple_bloods_declare_before_any_destination_finishes(){let(mut g,host,_)=setup();attach(&mut g,"BQ040",&host);g.return_hand(&host);g.drive().unwrap();assert_eq!(g.death_replacements.len(),2);choose(&mut g,vec!["accept".into()]);assert!(g.pending.is_some());restore(&mut g);choose(&mut g,vec!["accept".into()]);drain(&mut g);assert_eq!(g.sealed_cards.iter().filter(|c|matches!(c.card.definition.as_str(),"XQ14"|"BQ040")).count(),2);assert!(g.death_replacements.is_empty());}
#[test]fn msbq01_pending_identity_destination_and_missing_barrier_corruption_rejected(){let(mut g,host,_)=setup();g.return_hand(&host);g.drive().unwrap();for n in 0..8{let mut x=g.clone();match n{0=>x.death_replacements[0].blood.as_mut().unwrap().host.card.controller=2,1=>x.death_replacements[0].card.as_mut().unwrap().owner=1,2=>x.death_replacements.push(x.death_replacements[0].clone()),3=>x.death_replacements[0].destination=Some(crate::death_continuation::DeathDestination::Removed),4=>x.effects.retain(|e|!matches!(e,Effect::DeathFinish{..})),5=>x.pending.as_mut().unwrap().choice.min=Some(1),6=>x.death_replacements[0].declaration_choice=Some("i1".into()),_=>x.death_replacements[0].blood.as_mut().unwrap().society.card.id="i1".into()}bad(&g,&x);}let a=Action{choice_id:Some(g.pending.as_ref().unwrap().choice.id.clone()),selected:Some(vec!["accept".into()]),..Action::new("choose")};reject(&mut g,1,a.clone());reject(&mut g,0,Action{amount:Some(1),..a.clone()});act(&mut g,0,a.clone());reject(&mut g,0,a);drain(&mut g);}
#[test]fn msbq01_cancelled_original_response_buries_once(){let(mut g,host,_)=setup();g.return_hand(&host);g.drive().unwrap();choose(&mut g,vec!["accept".into()]);let i=g.stack.pop().unwrap();assert_eq!(i.frame.unwrap().ability_key,b::KEY);g.drive().unwrap();restore(&mut g);assert!(g.death_replacements.is_empty());assert_eq!(g.players[0].graveyard.iter().filter(|c|c.definition=="XQ14").count(),1);}
#[test]fn msbq01_jc028_transformed_blood_returns_to_printed_identity_when_sealed(){let(mut g,host,blood)=setup();g.return_hand(&blood);let c=field(&mut g,"JC028",0);act(&mut g,0,Action{card_id:Some(c),ability_id:Some(crate::jc028::KEY.into()),target_id:Some(host.clone()),..Action::new("activate")});drain(&mut g);assert!(g.attachments.iter().any(|a|a.card.definition==crate::jc028::FORM));g.return_hand(&host);g.drive().unwrap();restore(&mut g);choose(&mut g,vec!["accept".into()]);drain(&mut g);assert!(g.sealed_cards.iter().any(|s|s.card.definition=="JC028"&&s.card.blood_origin.is_none()));}
use crate::abi112_review_play_tests::Trace;
fn settle_trace(t:&mut Trace){for _ in 0..60{if t.room.game.pending.is_some()||t.room.game.stack.is_empty(){return;}t.pass();}panic!()}
#[test]fn msbq01_real_room_nested_bounce_restore_and_duplicate(){let(mut g,a,_)=setup();let bhost=field(&mut g,"JC029",0);attach(&mut g,"BQ040",&bhost);fund(&mut g,2,"JC006",4);let first=held(&mut g,"JC006",2);let second=held(&mut g,"JC006",2);g.begin_window(Window::Action(g.team(2)));let mut t=Trace::new_preserving_rng(g,"msbq01-closed-prepared-nested-return".into(),901);for (card,host) in [(first,a),(second,bhost)]{let action=Action{card_id:Some(card.clone()),target_id:Some(host),..Action::new("play")};if t.room.pacing.window.is_some(){for _ in 0..8{if t.room.pacing.window.as_ref().is_some_and(|w|matches!(w.members.get(&2),Some(crate::room::Decision::Undecided{..}))){break;}t.pass();}let w=t.room.pacing.window.clone().unwrap();let intent_id=format!("blood-response-{card}");t.step(2,crate::room::SessionAction::BeginResponse{window_id:w.id.clone(),intent_id:intent_id.clone()});t.step(2,crate::room::SessionAction::SubmitResponse{window_id:w.id,intent_id,action});}else{t.action(2,action);}settle_trace(&mut t);assert!(t.room.game.pending.is_some());t.choose(vec!["accept".into()]);}assert_eq!(t.room.game.death_replacements.len(),2);for _ in 0..80{if t.room.game.pending.is_none()&&t.room.game.stack.is_empty(){break;}if t.room.game.pending.is_some(){t.choose(vec![]);}else{t.pass();}}assert!(t.room.game.death_replacements.is_empty());assert_eq!(t.room.game.sealed_cards.iter().filter(|s|matches!(s.card.definition.as_str(),"XQ14"|"BQ040")).count(),2);let mut v=t.value();for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let dup=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();let command:crate::room::RoomCommand=serde_json::from_value(s["command"].clone()).unwrap();if matches!(command.action,crate::room::SessionAction::BeginResponse{..}){assert_eq!(dup.outcome,"accepted");assert!(dup.changed);let mut replay=crate::room::RoomEnvelope::from_persisted(&dup.state).unwrap();assert_eq!(replay.revision,r.revision+1);replay.revision=r.revision;replay.game.version=r.game.version;assert_eq!(serde_json::to_value(&replay).unwrap(),serde_json::to_value(&r).unwrap());s["duplicateKind"]=serde_json::json!("same-intent composition acknowledgement; no gameplay replay");}else{assert_eq!(dup.outcome,"rejected");assert!(!dup.changed&&dup.journal.is_empty());assert_eq!(dup.state,s["expected"]["state"]);s["duplicateKind"]=serde_json::json!("rejected without state change");}s["duplicate"]=serde_json::to_value(dup).unwrap();}let mut binding=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(name,bytes)in[("rust-game/src/msbq01.rs",include_bytes!("msbq01.rs").as_slice()),("rust-game/src/msbq01_tests.rs",include_bytes!("msbq01_tests.rs").as_slice()),("rust-game/src/death_continuation.rs",include_bytes!("death_continuation.rs").as_slice()),("rust-game/src/attachment.rs",include_bytes!("attachment.rs").as_slice()),("rust-game/src/mystic_contest.rs",include_bytes!("mystic_contest.rs").as_slice())]{binding["files"][name]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}v["sourceBindings"]=binding;if let Ok(path)=std::env::var("MSBQ01_NATIVE_OUT"){std::fs::write(path,serde_json::to_vec(&v).unwrap()).unwrap();}}
#[test]fn msbq01_cq15_original_search_waits_for_attachment_destination(){let(mut g,target,_)=setup();let attacker=field(&mut g,"JC125",1);fund(&mut g,1,"LC16",6);let sword=held(&mut g,"CQ15",1);g.begin_window(Window::Action(g.team(1)));act(&mut g,1,Action{card_id:Some(sword),target_id:Some(attacker.clone()),..Action::new("play")});drain(&mut g);let sword=g.attachments.iter().find(|a|a.card.definition=="CQ15").unwrap().card.id.clone();g.begin_window(Window::Action(g.team(1)));act(&mut g,1,Action{card_id:Some(attacker),ability_id:Some(format!("{}{}",crate::import20_swords::PREFIX,sword)),target_id:Some(target),..Action::new("activate")});for _ in 0..40{if g.pending.is_some(){break;}pass(&mut g);}assert!(matches!(&g.pending.as_ref().unwrap().resolution,ChoiceResolution::Declare{declaration:d,..}if d.ability.key==b::KEY));assert!(g.effects.iter().any(|e|matches!(e,Effect::DeathCaller{..})));let mut x=g.clone();let c=x.effects.iter_mut().find_map(|e|if let Effect::DeathCaller{caller}=e{Some(caller)}else{None}).unwrap();c.waits[0].blood=None;bad(&g,&x);restore(&mut g);choose(&mut g,vec!["accept".into()]);for _ in 0..40{if g.pending.is_some(){break;}pass(&mut g);}assert_eq!(g.pending.as_ref().unwrap().choice.kind,crate::import20_swords::SEARCH);assert!(g.death_replacements.is_empty());assert!(g.sealed_cards.iter().any(|s|s.card.definition=="XQ14"));let selected=g.pending.as_ref().unwrap().choice.options.iter().map(|o|o.id.clone()).collect();choose(&mut g,selected);drain(&mut g);}
#[test]fn msbq01_actual_response_cannot_lose_frame_or_swap_source(){let(mut g,host,_)=setup();g.return_hand(&host);g.drive().unwrap();choose(&mut g,vec!["accept".into()]);for n in 0..3{let mut x=g.clone();match n{0=>x.stack.last_mut().unwrap().frame=None,1=>{let f=x.stack.last_mut().unwrap().frame.as_mut().unwrap();f.source.card.definition="JC001".into();f.ability_key="foreign".into();f.steps.clear();},_=>x.death_replacements[0].declared_frame=Some("i1".into())}bad(&g,&x);}restore(&mut g);drain(&mut g);}
fn constructed(seed:u64,has_blood:bool)->Game{let mut d=crate::deck::preset("watchers").unwrap();d.id="closed-msbq01-natural".into();d.society_id=Some(b::ID.into());d.core_card_id=None;d.cards=if has_blood{vec![crate::catalog::DeckEntry{card_id:"XQ14".into(),count:8},crate::catalog::DeckEntry{card_id:"JC125".into(),count:42}]}else{vec![crate::catalog::DeckEntry{card_id:"JC125".into(),count:50}]};assert!(crate::deck::validate(d.clone()).is_err());let mut societies=crate::catalog::catalog().societies.clone();societies.iter_mut().find(|s|s.card.id==b::ID).unwrap().card.supported=true;let d=crate::deck::validate_with_registry(d,&crate::catalog::catalog().cards,&societies).unwrap();let mut other=crate::deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![crate::catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=crate::deck::validate(other).unwrap();let mut g=Game::new("msbq01-natural".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}
#[test]fn msbq01_printed_construction_and_name_copy_exception(){let s=crate::society::definition(b::ID).unwrap();assert!(!s.card.supported);for c in &crate::catalog::catalog().cards{assert_eq!(crate::society::validate_construction(s,&[crate::catalog::DeckEntry{card_id:c.id.clone(),count:1}],&crate::catalog::catalog().cards).is_ok(),matches!(c.color.as_str(),"蓝"|"绿"|"中立"),"{}",c.id);}assert_eq!(crate::deck::copy_limit_for_society(crate::catalog::card("XQ14"),Some(b::ID)),None);assert_eq!(crate::deck::copy_limit_for_society(crate::catalog::card("XQ14"),None),Some(3));}
#[test]fn msbq01_real_prehand_search_then_draw_no_blood_and_replay(){for has in [true,false]{let mut g=constructed(12,has);if has{assert!(g.players[0].hand.is_empty());let p=g.pending.clone().unwrap();assert!(matches!(p.resolution,ChoiceResolution::MSBQ01Opening{seat:0}));assert_eq!(p.choice.options.len(),8);restore(&mut g);for ids in [vec![],vec![p.choice.options[0].id.clone(),p.choice.options[1].id.clone()]]{reject(&mut g,0,Action{choice_id:Some(p.choice.id.clone()),selected:Some(ids),..Action::new("choose")});}let a=Action{choice_id:Some(p.choice.id),selected:Some(vec![p.choice.options[0].id.clone()]),..Action::new("choose")};g.apply(0,a.clone()).unwrap();restore(&mut g);reject(&mut g,0,a);}assert_eq!(g.players[0].hand.len(),6);assert_eq!(g.players[0].deck.len(),44-usize::from(has));assert_eq!(g.sealed_cards.len(),usize::from(has));restore(&mut g);}}
#[test]fn msbq01_opening_corrupt_choice_or_missing_continuation_rejected(){let g=constructed(12,true);for n in 0..6{let mut x=g.clone();match n{0=>x.pending=None,1=>x.pending.as_mut().unwrap().seat=1,2=>x.pending.as_mut().unwrap().choice.min=Some(0),3=>x.pending.as_mut().unwrap().choice.options.clear(),4=>x.effects.push_back(Effect::MSBQ01Opening{seat:0}),_=>{x.players[0].society_zone.used_once_per_game.remove("msbq01-opening");}}bad(&g,&x);}}
fn natural_construct(seed:u64)->Game{let mut d=crate::deck::preset("watchers").unwrap();d.id="closed-msbq01-complete-chain".into();d.society_id=Some(b::ID.into());d.core_card_id=None;d.cards=[("XQ14",12),("JC029",3),("JC125",35)].into_iter().map(|(id,count)|crate::catalog::DeckEntry{card_id:id.into(),count}).collect();let mut societies=crate::catalog::catalog().societies.clone();societies.iter_mut().find(|s|s.card.id==b::ID).unwrap().card.supported=true;assert!(crate::deck::validate(d.clone()).is_err());let d=crate::deck::validate_with_registry(d,&crate::catalog::catalog().cards,&societies).unwrap();let mut other=crate::deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=[("JC006",3),("JC125",47)].into_iter().map(|(id,count)|crate::catalog::DeckEntry{card_id:id.into(),count}).collect();let other=crate::deck::validate(other).unwrap();let mut g=Game::new("msbq01-natural".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}
#[test]fn msbq01_natural_construct_search_attach_return_and_seal_room(){use crate::abi112_review_play_tests::Trace;let(seed,g)=(1..4097).find_map(|seed|{let g=natural_construct(seed);let mut probe=g.clone();while let Some(p)=probe.pending.clone(){let ids=if matches!(p.resolution,ChoiceResolution::MSBQ01Opening{..}){vec![p.choice.options[0].id.clone()]}else{vec![]};choose(&mut probe,ids);}let h=&probe.players[0].hand;let good=h.iter().any(|c|c.definition=="JC029")&&h.iter().filter(|c|c.definition=="XQ14").count()>=2&&probe.players[1].hand.iter().filter(|c|c.definition=="JC006").count()>=2;good.then_some((seed,g))}).expect("bounded legal dealt hands");let deck=g.players[0].deck_snapshot.clone().unwrap();let mut t=Trace::new_preserving_rng(g,"msbq01-natural-opening-attachment-departure".into(),812);let mut attached=false;let mut bounced=false;for _ in 0..1500{if let Some(p)=t.room.game.pending.clone(){let ids=match &p.resolution{ChoiceResolution::MSBQ01Opening{..}=>vec![p.choice.options[0].id.clone()],ChoiceResolution::Declare{declaration:d,..}if d.ability.key==b::KEY=>vec!["accept".into()],_=>{let mut os=p.choice.options.iter().collect::<Vec<_>>();os.sort_by_key(|o|t.room.game.players[p.seat].hand.iter().any(|c|c.id==o.id&&matches!(c.definition.as_str(),"JC029"|"JC006"|"XQ14")));os.into_iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect()}};t.choose(ids);continue;}if bounced&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}if !t.room.game.stack.is_empty()||t.room.pacing.window.is_some(){t.pass();continue;}let g=&t.room.game;let host=g.regions.iter().flat_map(|r|&r.cards).find(|c|c.definition=="JC029"&&c.controller==0&&!c.face_down).map(|c|c.id.clone());let mut pick=None;for seat in [0,1]{let legal=g.legal_actions(seat);let wanted=if g.players[seat].assets.len()<3{let color=g.players[seat].assets.iter().filter(|c|c.definition==if seat==0{"XQ14"}else{"JC006"}).count()>=if seat==0{2}else{1};legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[seat].hand.iter().any(|c|&c.id==id&&c.definition==if color{"JC125"}else if seat==0{"XQ14"}else{"JC006"})))}else if seat==0&&host.is_none()&&!attached{legal.iter().find(|a|a.action.kind=="deploy"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="JC029")))}else if seat==0&&host.is_some()&&!attached{legal.iter().find(|a|a.action.kind=="play"&&a.action.target_id==host&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="XQ14")))}else if seat==1&&attached&&!bounced{legal.iter().find(|a|a.action.kind=="play"&&a.action.target_id==host&&a.action.card_id.as_ref().is_some_and(|id|g.players[1].hand.iter().any(|c|&c.id==id&&c.definition=="JC006")))}else{None};if let Some(a)=wanted{pick=Some((seat,a.action.clone()));break;}}if let Some((seat,a))=pick{if a.kind=="play"{if seat==0{attached=true;}else{bounced=true;}}t.action(seat,a);}else{t.pass();}}
 assert!(attached&&bounced,"natural chain missing at turn {} attached={attached} bounced={bounced}",t.room.game.turn);assert_eq!(t.room.game.sealed_cards.iter().filter(|c|c.card.definition=="XQ14"&&c.host_id=="society:p0").count(),2);assert!(t.room.game.death_replacements.is_empty());assert!(t.room.game.players[0].hand.iter().any(|c|c.definition=="JC029"));let mut v=t.value();v["construction"]=serde_json::json!({"deck":deck,"seed":seed,"privateRegistryOnly":true,"privateRegistryCandidates":[b::ID],"noLayoutOrResourceMutation":true});for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.outcome,"rejected");assert_eq!(d.state,s["expected"]["state"]);s["duplicate"]=serde_json::to_value(d).unwrap();}if let Ok(path)=std::env::var("MSBQ01_NATURAL_OUT"){std::fs::write(path,serde_json::to_vec(&v).unwrap()).unwrap();}}
